/*
 * Pico 2 W — RGB LED Color Cycle
 * Cycles through R, G, B, and mixed colors
 * using PWM on GP10, GP11, GP12
 */

#define RED_PIN   10
#define GREEN_PIN 11
#define BLUE_PIN  12

void setColor(int r, int g, int b) {
  analogWrite(RED_PIN, r);
  analogWrite(GREEN_PIN, g);
  analogWrite(BLUE_PIN, b);
}

void setup() {
  pinMode(RED_PIN, OUTPUT);
  pinMode(GREEN_PIN, OUTPUT);
  pinMode(BLUE_PIN, OUTPUT);
  Serial.begin(115200);
  Serial.println("RGB LED Color Cycle!");
}

void loop() {
  // Red
  setColor(255, 0, 0);
  Serial.println("RED");
  delay(1000);

  // Green
  setColor(0, 255, 0);
  Serial.println("GREEN");
  delay(1000);

  // Blue
  setColor(0, 0, 255);
  Serial.println("BLUE");
  delay(1000);

  // Yellow (R+G)
  setColor(255, 255, 0);
  Serial.println("YELLOW");
  delay(1000);

  // Cyan (G+B)
  setColor(0, 255, 255);
  Serial.println("CYAN");
  delay(1000);

  // Magenta (R+B)
  setColor(255, 0, 255);
  Serial.println("MAGENTA");
  delay(1000);

  // White (R+G+B)
  setColor(255, 255, 255);
  Serial.println("WHITE");
  delay(1000);

  // Off
  setColor(0, 0, 0);
  delay(500);
}
